/** The category page: /blog/category/<slug>. */
export const categoryPath = (slug) => `${BLOG_BASE}/category/${encodeSlugPath(slug)}`;
/** The tag page: /blog/tag/<slug>. */
export const tagPath = (slug) => `${BLOG_BASE}/tag/${encodeSlugPath(slug)}`;
// ---- media ---------------------------------------------------------------------------------
/**
