        id: rawId(raw),
        slug: raw.slug ?? "",
        title: raw.title ?? "",
        excerpt: raw.excerpt ?? "",
        ...dateParts(raw.firstPublishedDate),
        minutesToRead: raw.minutesToRead ?? 0,
        featured: raw.featured === true,
        pinned: raw.pinned === true,
        ...coverOf(raw, imgSrc),
        categoryIds: raw.categoryIds ?? [],
        tagIds: raw.tagIds ?? [],
        authorId: raw.memberId ?? "",
        authorName: "",
        authorAvatarUrl: "",
