 * cursor request carries ONLY cursorPaging; the first page carries the sort and the filters.
 */
export function feedQuery({ limit = 20, cursor, categoryId, tagId } = {}) {
    if (cursor)
        return { cursorPaging: { limit, cursor } };
    const filter = {};
